CREATE TABLE en1994_document (id INTEGER PRIMARY KEY CHECK(id=1),annex TEXT NOT NULL CHECK(annex IN ('En','De')),structure_kind TEXT NOT NULL,steel_f_y_pa REAL,fire_rating TEXT NOT NULL,insulation_thickness_m REAL,fatigue_detail TEXT NOT NULL,steel_f_y_pa_ieee754_bits INTEGER NOT NULL,steel_f_y_pa_ieee754_class TEXT NOT NULL,insulation_thickness_m_ieee754_bits INTEGER NOT NULL,insulation_thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,span_m REAL,spacing_m REAL,support TEXT NOT NULL,construction TEXT NOT NULL,slab_thickness_m REAL,concrete_f_ck_pa REAL,concrete_e_cm_pa REAL,transverse_as_m2_per_m REAL,ltb_length_m REAL,as_hogging_m2_per_m REAL,bar_spacing_m REAL,wk_limit_m REAL,n_cycles REAL,span_m_ieee754_bits INTEGER NOT NULL,span_m_ieee754_class TEXT NOT NULL,spacing_m_ieee754_bits INTEGER NOT NULL,spacing_m_ieee754_class TEXT NOT NULL,slab_thickness_m_ieee754_bits INTEGER NOT NULL,slab_thickness_m_ieee754_class TEXT NOT NULL,concrete_f_ck_pa_ieee754_bits INTEGER NOT NULL,concrete_f_ck_pa_ieee754_class TEXT NOT NULL,concrete_e_cm_pa_ieee754_bits INTEGER NOT NULL,concrete_e_cm_pa_ieee754_class TEXT NOT NULL,transverse_as_m2_per_m_ieee754_bits INTEGER NOT NULL,transverse_as_m2_per_m_ieee754_class TEXT NOT NULL,ltb_length_m_ieee754_bits INTEGER NOT NULL,ltb_length_m_ieee754_class TEXT NOT NULL,as_hogging_m2_per_m_ieee754_bits INTEGER NOT NULL,as_hogging_m2_per_m_ieee754_class TEXT NOT NULL,bar_spacing_m_ieee754_bits INTEGER NOT NULL,bar_spacing_m_ieee754_class TEXT NOT NULL,wk_limit_m_ieee754_bits INTEGER NOT NULL,wk_limit_m_ieee754_class TEXT NOT NULL,n_cycles_ieee754_bits INTEGER NOT NULL,n_cycles_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_steel (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id) CHECK(beam_id=id),designation TEXT NOT NULL,height_m REAL,width_m REAL,tw_m REAL,tf_m REAL,a_m2 REAL,w_pl_y_m3 REAL,i_y_m4 REAL,a_v_m2 REAL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,width_m_ieee754_bits INTEGER NOT NULL,width_m_ieee754_class TEXT NOT NULL,tw_m_ieee754_bits INTEGER NOT NULL,tw_m_ieee754_class TEXT NOT NULL,tf_m_ieee754_bits INTEGER NOT NULL,tf_m_ieee754_class TEXT NOT NULL,a_m2_ieee754_bits INTEGER NOT NULL,a_m2_ieee754_class TEXT NOT NULL,w_pl_y_m3_ieee754_bits INTEGER NOT NULL,w_pl_y_m3_ieee754_class TEXT NOT NULL,i_y_m4_ieee754_bits INTEGER NOT NULL,i_y_m4_ieee754_class TEXT NOT NULL,a_v_m2_ieee754_bits INTEGER NOT NULL,a_v_m2_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_sheeting (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id) CHECK(beam_id=id),profile TEXT NOT NULL,height_m REAL,rib_width_m REAL,thickness_m REAL,ribs_parallel_to_beam INTEGER NOT NULL CHECK(ribs_parallel_to_beam IN (0,1)),height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,rib_width_m_ieee754_bits INTEGER NOT NULL,rib_width_m_ieee754_class TEXT NOT NULL,thickness_m_ieee754_bits INTEGER NOT NULL,thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_studs (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id) CHECK(beam_id=id),diameter_m REAL,height_m REAL,f_u_pa REAL,count_per_rib INTEGER NOT NULL CHECK(count_per_rib BETWEEN 0 AND 4294967295),spacing_m REAL,total_count INTEGER NOT NULL CHECK(total_count BETWEEN 0 AND 4294967295),diameter_m_ieee754_bits INTEGER NOT NULL,diameter_m_ieee754_class TEXT NOT NULL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,f_u_pa_ieee754_bits INTEGER NOT NULL,f_u_pa_ieee754_class TEXT NOT NULL,spacing_m_ieee754_bits INTEGER NOT NULL,spacing_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_action (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,stage TEXT NOT NULL,q_area_pa REAL,f_k_n REAL,delta_sigma_k_pa REAL,delta_tau_k_pa REAL,q_area_pa_ieee754_bits INTEGER NOT NULL,q_area_pa_ieee754_class TEXT NOT NULL,f_k_n_ieee754_bits INTEGER NOT NULL,f_k_n_ieee754_class TEXT NOT NULL,delta_sigma_k_pa_ieee754_bits INTEGER NOT NULL,delta_sigma_k_pa_ieee754_class TEXT NOT NULL,delta_tau_k_pa_ieee754_bits INTEGER NOT NULL,delta_tau_k_pa_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_column (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL,length_m REAL,outer_size_m REAL,wall_thickness_m REAL,steel_a_m2 REAL,steel_f_y_pa REAL,concrete_a_m2 REAL,concrete_f_ck_pa REAL,reinforcement_as_m2 REAL,reinforcement_f_yk_pa REAL,i_m4 REAL,buckling_curve TEXT NOT NULL,length_m_ieee754_bits INTEGER NOT NULL,length_m_ieee754_class TEXT NOT NULL,outer_size_m_ieee754_bits INTEGER NOT NULL,outer_size_m_ieee754_class TEXT NOT NULL,wall_thickness_m_ieee754_bits INTEGER NOT NULL,wall_thickness_m_ieee754_class TEXT NOT NULL,steel_a_m2_ieee754_bits INTEGER NOT NULL,steel_a_m2_ieee754_class TEXT NOT NULL,steel_f_y_pa_ieee754_bits INTEGER NOT NULL,steel_f_y_pa_ieee754_class TEXT NOT NULL,concrete_a_m2_ieee754_bits INTEGER NOT NULL,concrete_a_m2_ieee754_class TEXT NOT NULL,concrete_f_ck_pa_ieee754_bits INTEGER NOT NULL,concrete_f_ck_pa_ieee754_class TEXT NOT NULL,reinforcement_as_m2_ieee754_bits INTEGER NOT NULL,reinforcement_as_m2_ieee754_class TEXT NOT NULL,reinforcement_f_yk_pa_ieee754_bits INTEGER NOT NULL,reinforcement_f_yk_pa_ieee754_class TEXT NOT NULL,i_m4_ieee754_bits INTEGER NOT NULL,i_m4_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_column_action (id INTEGER PRIMARY KEY,column_id INTEGER NOT NULL REFERENCES en1994_column(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,stage TEXT NOT NULL,n_k_n REAL,m_k_nm REAL,n_k_n_ieee754_bits INTEGER NOT NULL,n_k_n_ieee754_class TEXT NOT NULL,m_k_nm_ieee754_bits INTEGER NOT NULL,m_k_nm_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_slab (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,span_m REAL,support TEXT NOT NULL,concrete_thickness_m REAL,f_ck_pa REAL,m_factor REAL,k_factor REAL,as_m2_per_m REAL,span_m_ieee754_bits INTEGER NOT NULL,span_m_ieee754_class TEXT NOT NULL,concrete_thickness_m_ieee754_bits INTEGER NOT NULL,concrete_thickness_m_ieee754_class TEXT NOT NULL,f_ck_pa_ieee754_bits INTEGER NOT NULL,f_ck_pa_ieee754_class TEXT NOT NULL,m_factor_ieee754_bits INTEGER NOT NULL,m_factor_ieee754_class TEXT NOT NULL,k_factor_ieee754_bits INTEGER NOT NULL,k_factor_ieee754_class TEXT NOT NULL,as_m2_per_m_ieee754_bits INTEGER NOT NULL,as_m2_per_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_slab_sheeting (id INTEGER PRIMARY KEY,slab_id INTEGER NOT NULL REFERENCES en1994_slab(id) CHECK(slab_id=id),profile TEXT NOT NULL,height_m REAL,rib_width_m REAL,thickness_m REAL,ribs_parallel_to_beam INTEGER NOT NULL CHECK(ribs_parallel_to_beam IN (0,1)),height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,rib_width_m_ieee754_bits INTEGER NOT NULL,rib_width_m_ieee754_class TEXT NOT NULL,thickness_m_ieee754_bits INTEGER NOT NULL,thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_slab_action (id INTEGER PRIMARY KEY,slab_id INTEGER NOT NULL REFERENCES en1994_slab(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,stage TEXT NOT NULL,q_area_pa REAL,f_k_n REAL,delta_sigma_k_pa REAL,delta_tau_k_pa REAL,q_area_pa_ieee754_bits INTEGER NOT NULL,q_area_pa_ieee754_class TEXT NOT NULL,f_k_n_ieee754_bits INTEGER NOT NULL,f_k_n_ieee754_class TEXT NOT NULL,delta_sigma_k_pa_ieee754_bits INTEGER NOT NULL,delta_sigma_k_pa_ieee754_class TEXT NOT NULL,delta_tau_k_pa_ieee754_bits INTEGER NOT NULL,delta_tau_k_pa_ieee754_class TEXT NOT NULL);
